mapper.select:
select
id,
has_handler as hasHandler,
paying_agency as payingAgency,
pay_type as payType,
mch_no as mchNo,
trx_id as trxId,
interface_code as interfaceCode,
create_time as createTime
from callback_handler_log


        and mch_no = #{pageDTO.mchNo}


        and trx_id = #{pageDTO.trxId}


        and paying_agency = #{pageDTO.payingAgency}


        and pay_type = #{pageDTO.payType}


        and interface_code = #{pageDTO.interfaceCode}


        and has_handler = #{pageDTO.hasHandler}


order by create_time desc
